import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        switch (n) {
            case 1:
                System.out.println("上{dish}喵");
                break;
            case 2:
                System.out.println("加一碗鱼汤喵");
                break;
            case 3:
                System.out.println("上清水喵");
                break;
            default:
                System.out.println("本喵没这道菜喵");
        }
    }
}
